Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
#define fo(a,b,c) for (a=b; a<=c; a++)
#define fd(a,b,c) for (a=b; a>=c; a--)
#define add(a,b) a=((a)+(b))%mod
#define min(a,b) (a<b?a:b)
#define ll long long
//#define file
using namespace std;

ll jc[501],Jc[501],f[501],g[501],h[501][501][2],C[501][501],s,ans,F;
int n,m,mod,Mod,i,j,k,l;

ll qpower(ll a,int b) {ll ans=1; while (b) {if (b&1) ans=ans*a%mod;a=a*a%mod;b>>=1;} return ans;}

int main()
{
	#ifdef file
	freopen("CF1439D.in","r",stdin);
	#endif

	scanf("%d%d%d",&n,&m,&mod),Mod=mod-2;
	jc[0]=1;
	fo(i,1,n) jc[i]=jc[i-1]*i%mod;
	Jc[n]=qpower(jc[n],Mod);
	fd(i,n-1,0) Jc[i]=Jc[i+1]*(i+1)%mod;
	C[0][0]=1;
	fo(i,1,n)
	{
		C[i][0]=C[i][i]=1;
		fo(j,1,i-1) C[i][j]=(C[i-1][j-1]+C[i-1][j])%mod;
	}

	f[0]=1;g[0]=0;
	fo(i,1,m)
	{
		fo(j,1,i)
		{
			s=(j*(j-1)/2+(i-j+1)*(i-j)/2)%mod;
			add(f[i],f[j-1]*f[i-j]%mod*(i+1)%mod*C[i-1][j-1]);
			add(g[i],((g[j-1]*f[i-j]+f[j-1]*g[i-j])%mod*(i+1)+f[j-1]*f[i-j]%mod*s)%mod*C[i-1][j-1]);
		}
	}

	h[0][0][0]=1;
	fo(i,0,min(m,n-m+1)-1)
	{
		fo(j,0,m-1)
		{
			fo(k,1,m-j)
			{
				F=f[k]*C[j+k][j]%mod;
				add(h[i+1][j+k][0],h[i][j][0]*F);
				add(h[i+1][j+k][1],h[i][j][1]*F);
				add(h[i+1][j+k][1],h[i][j][0]*g[k]%mod*C[j+k][j]);
			}
		}
	}

	fo(i,1,min(m,n-m+1)) add(ans,h[i][m][1]*C[n-m+1][i]);
	printf("%lld\n",(ans+mod)%mod);

	fclose(stdin);
	fclose(stdout);
	return 0;
}
</original_code>
